23	/**
24	 * 原子改签 API 主流程、失败回滚、改签链与幂等边界的端到端测试（H2 内存库）。
25	 * 各用例使用唯一 scheduleKey/requestKey/区段 ID，共享库内互不干扰。
26	 */
27	@SpringBootTest
28	@AutoConfigureMockMvc
29	class PlanRescheduleApiTest {
30	
31	    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
32	    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);
33	
34	    @Autowired
35	    private MockMvc mvc;
36	
37	    @Autowired
38	    private ObjectMapper objectMapper;
39	
40	    // ---------- 主流程 ----------
41	
42	    @Test
43	    void rescheduleCancelsOldPublishesNewAndAppendsLink() throws Exception {
44	        String section = key("SEC");
45	        String oldKey = key("SCH");
46	        String newKey = key("SCH");
47	        createPlan(oldKey, occ("G1", section, iso(8), iso(9)));
48	        publishPlan(oldKey, key("REQ"));
49	        // 新草稿复用旧计划自身时隙（08:00-09:30 覆盖旧 08:00-09:00），改签校验须排除旧计划占用
50	        createPlan(newKey, occ("G2", section, iso(8), iso(9, 30)));
51	
52	        MvcResult result = mvc.perform(post("/api/v1/plans/{key}/reschedule", oldKey)
53	                        .contentType(MediaType.APPLICATION_JSON)
54	                        .content(rescheduleBody(key("REQ"), newKey, 1, 1)))
55	                .andExpect(status().isOk()).andReturn();
56	        JsonNode body = read(result);
57	        JsonNode oldPlan = body.get("oldPlan");
58	        JsonNode newPlan = body.get("newPlan");
59	        assertThat(oldPlan.get("scheduleKey").asText()).isEqualTo(oldKey);
60	        assertThat(oldPlan.get("status").asText()).isEqualTo("CANCELLED");
61	        assertThat(oldPlan.get("version").asInt()).isEqualTo(1);
62	        assertThat(newPlan.get("scheduleKey").asText()).isEqualTo(newKey);
63	        assertThat(newPlan.get("status").asText()).isEqualTo("PUBLISHED");
64	        assertThat(newPlan.get("version").asInt()).isEqualTo(1);
65	
66	        // 旧计划原始占用保留不覆盖
67	        MvcResult oldDetail = mvc.perform(get("/api/v1/plans/{key}", oldKey))
68	                .andExpect(status().isOk()).andReturn();
69	        JsonNode oldBody = read(oldDetail);
70	        assertThat(oldBody.get("status").asText()).isEqualTo("CANCELLED");
71	        assertThat(oldBody.get("occupancies")).hasSize(1);
72	        assertThat(oldBody.get("occupancies").get(0).get("trainNo").asText()).isEqualTo("G1");
73	        assertThat(oldBody.get("occupancies").get(0).get("startUtc").asText()).isEqualTo(iso(8));
74	
75	        // 生效时隙切换为新计划
76	        MvcResult slots = mvc.perform(get("/api/v1/published-slots")
77	                        .param("date", DAY.toString()).param("sectionId", section))
78	                .andExpect(status().isOk()).andReturn();
79	        JsonNode slotList = read(slots);
80	        assertThat(slotList).hasSize(1);
81	        assertThat(slotList.get(0).get("scheduleKey").asText()).isEqualTo(newKey);
82	        assertThat(slotList.get(0).get("endUtc").asText()).isEqualTo(iso(9, 30));
83	
84	        // 前后继关联可从两侧查询，链完整有序
85	        assertChainKeys(oldKey, oldKey, newKey);
86	        assertChainKeys(newKey, oldKey, newKey);
87	    }
