6	import com.example.starter.plan.web.ApiException;
7	import com.example.starter.plan.web.dto.CreatePlanRequest;
8	import com.example.starter.plan.web.dto.OccupancyRequest;
9	import com.example.starter.plan.web.dto.RescheduleChainResponse;
10	import com.example.starter.plan.web.dto.RescheduleRequest;
11	import java.time.Instant;
12	import java.time.LocalDate;
13	import java.time.ZoneId;
14	import java.util.ArrayList;
15	import java.util.List;
16	import java.util.UUID;
17	import java.util.concurrent.Callable;
18	import java.util.concurrent.CountDownLatch;
19	import java.util.concurrent.ExecutorService;
20	import java.util.concurrent.Executors;
21	import java.util.concurrent.Future;
22	import java.util.concurrent.TimeUnit;
23	import org.junit.jupiter.api.Test;
24	import org.springframework.beans.factory.annotation.Autowired;
25	import org.springframework.boot.test.context.SpringBootTest;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.jdbc.core.JdbcTemplate;
28	
29	/**
30	 * 改签并发裁决测试：同一旧计划的并发改签最多一次成功；
31	 * 改签与第三方发布竞争同一时隙时按事务提交顺序裁决，第三方抢不到改签后已占用的时隙。
32	 */
33	@SpringBootTest
34	class PlanRescheduleConcurrencyTest {
35	
36	    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
37	    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);
38	
39	    @Autowired
40	    private PlanService service;
41	
42	    @Autowired
43	    private JdbcTemplate jdbc;
44	
45	    @Test
46	    void concurrentRescheduleSameOldPlanOnlyOneSucceeds() throws Exception {
47	        String section = key("SEC");
48	        String oldKey = key("SCH");
49	        createDraft(oldKey, section, 8, 9);
50	        service.publish(oldKey, key("REQ"));
51	        String newA = key("SCH");
52	        String newB = key("SCH");
53	        createDraft(newA, section, 9, 10);
54	        createDraft(newB, section, 9, 10);
55	
56	        List<Outcome> outcomes = runConcurrently(List.of(
57	                () -> {
58	                    try {
59	                        service.reschedule(oldKey, new RescheduleRequest(key("REQ"), newA, 1, 1));
60	                        return Outcome.OK;
61	                    } catch (ApiException e) {
62	                        assertThat(e.status()).isEqualTo(HttpStatus.CONFLICT);
63	                        return Outcome.CONFLICT;
64	                    }
65	                },
66	                () -> {
67	                    try {
68	                        service.reschedule(oldKey, new RescheduleRequest(key("REQ"), newB, 1, 1));
69	                        return Outcome.OK;
70	                    } catch (ApiException e) {
71	                        assertThat(e.status()).isEqualTo(HttpStatus.CONFLICT);
72	                        return Outcome.CONFLICT;
73	                    }
74	                }));
75	
76	        // 同一旧计划的两次改签最多一次成功
77	        assertThat(outcomes.stream().filter(o -> o == Outcome.OK).count()).isEqualTo(1);
78	        assertThat(outcomes.stream().filter(o -> o == Outcome.CONFLICT).count()).isEqualTo(1);
79	
80	        // 旧计划只取消一次，恰好一个后继发布、另一个仍为草稿，关联仅一条
81	        assertThat(service.getPlan(oldKey).status()).isEqualTo("CANCELLED");
82	        String statusA = service.getPlan(newA).status();
83	        String statusB = service.getPlan(newB).status();
84	        assertThat(List.of(statusA, statusB)).containsExactlyInAnyOrder("PUBLISHED", "DRAFT");
85	        Integer linkCount = jdbc.queryForObject(
86	                "SELECT COUNT(*) FROM rail_plan_reschedule_link l"
87	                        + " JOIN rail_day_plan p ON p.id = l.predecessor_plan_id"
88	                        + " WHERE p.schedule_key = ?",
89	                Integer.class, oldKey);
90	        assertThat(linkCount).isEqualTo(1);
91	
92	        // 链完整有序且长度为 2
93	        RescheduleChainResponse chain = service.getRescheduleChain(oldKey);
94	        assertThat(chain.chain()).hasSize(2);
95	        assertThat(chain.chain().get(0).scheduleKey()).isEqualTo(oldKey);
96	        assertThat(chain.chain().get(0).status()).isEqualTo("CANCELLED");
97	        assertThat(chain.chain().get(1).status()).isEqualTo("PUBLISHED");
98	    }
99	
100	    @Test
101	    void concurrentRescheduleAndThirdPartyPublishRaceForSlot() throws Exception {
102	        String section = key("SEC");
103	        String oldKey = key("SCH");
104	        createDraft(oldKey, section, 8, 9);
105	        service.publish(oldKey, key("REQ"));
106	        // 改签新草稿与第三方草稿争夺同一时隙 10:00-11:00
107	        String newKey = key("SCH");
108	        String thirdParty = key("SCH");
109	        createDraft(newKey, section, 10, 11);
110	        createDraft(thirdParty, section, 10, 11);
111	
112	        List<Outcome> outcomes = runConcurrently(List.of(
113	                () -> {
114	                    try {
115	                        service.reschedule(oldKey, new RescheduleRequest(key("REQ"), newKey, 1, 1));
116	                        return Outcome.OK;
117	                    } catch (ApiException e) {
118	                        assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
119	                        return Outcome.CONFLICT;
120	                    }
121	                },
122	                () -> {
123	                    try {
124	                        service.publish(thirdParty, key("REQ"));
125	                        return Outcome.OK;
126	                    } catch (ApiException e) {
127	                        assertThat(e.status()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
128	                        return Outcome.CONFLICT;
129	                    }
130	                }));
131	
132	        // 恰好一方成功：第三方抢不到改签后已占用的时隙，反之改签整体回滚
133	        assertThat(outcomes.stream().filter(o -> o == Outcome.OK).count()).isEqualTo(1);
134	        String newStatus = service.getPlan(newKey).status();
135	        String thirdStatus = service.getPlan(thirdParty).status();
136	        if (outcomes.get(0) == Outcome.OK) {
137	            // 改签胜出：旧取消、新发布、第三方仍草稿
138	            assertThat(service.getPlan(oldKey).status()).isEqualTo("CANCELLED");
139	            assertThat(newStatus).isEqualTo("PUBLISHED");
140	            assertThat(thirdStatus).isEqualTo("DRAFT");
141	            assertThat(service.getRescheduleChain(oldKey).chain()).hasSize(2);
142	        } else {
143	            // 第三方先发布：改签 422 回滚，旧计划仍发布、新草稿仍草稿、无关联
144	            assertThat(service.getPlan(oldKey).status()).isEqualTo("PUBLISHED");
145	            assertThat(newStatus).isEqualTo("DRAFT");
146	            assertThat(thirdStatus).isEqualTo("PUBLISHED");
147	            assertThat(service.getRescheduleChain(oldKey).chain()).hasSize(1);
148	        }
149	
150	        // 最终该区段 10:00-11:00 只有一张计划的时隙生效
151	        assertThat(service.getPublishedSlots(DAY, section)
152	                .stream().filter(s -> s.startUtc().equals(at(10))).count())
153	                .isEqualTo(1);
154	    }
155	
156	    // ---------- 辅助 ----------
157	
158	    private enum Outcome {
159	        OK,
160	        CONFLICT
161	    }
162	
163	    private void createDraft(String scheduleKey, String section, int startHour, int endHour) {
164	        service.createDraft(new CreatePlanRequest(key("REQ"), scheduleKey, DAY,
165	                List.of(new OccupancyRequest("G-" + UUID.randomUUID(), section,
166	                        at(startHour), at(endHour)))));
167	    }
168	
169	    private List<Outcome> runConcurrently(List<Callable<Outcome>> tasks) throws Exception {
170	        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
171	        CountDownLatch ready = new CountDownLatch(tasks.size());
172	        CountDownLatch go = new CountDownLatch(1);
173	        List<Future<Outcome>> futures = tasks.stream()
174	                .map(t -> pool.submit(() -> {
175	                    ready.countDown();
176	                    go.await();
177	                    return t.call();
178	                })).toList();
179	        ready.await();
180	        go.countDown();
181	        List<Outcome> outcomes = new ArrayList<>();
182	        for (Future<Outcome> f : futures) {
183	            outcomes.add(f.get(30, TimeUnit.SECONDS));
184	        }
185	        pool.shutdown();
186	        return outcomes;
187	    }
188	
189	    private static Instant at(int hour) {
190	        return DAY.atTime(hour, 0).atZone(SH).toInstant();
191	    }
192	
193	    private static String key(String prefix) {
194	        return prefix + "-" + UUID.randomUUID();
195	    }
196	}
