                "SELECT COUNT(*) FROM rail_connection_decision d"
                        + " JOIN rail_day_plan p ON p.id = d.old_successor_plan_id"
                        + " WHERE p.schedule_key = ?",
                Integer.class, succ);
        assertThat(decisionCount).isEqualTo(1);
